-- Verified, always-open learning opportunities (official links checked on 2026-11-09; no deadlines invented).
insert into community.opportunities (title, organisation, description, eligibility, location, category, regions, audience, fields, deadline, apply_url, verified, last_checked, status)
select * from (values
('freeCodeCamp certifications','freeCodeCamp','A free, self-paced coding curriculum with projects and certifications in web development, JavaScript, Python, data and more.','Anyone. Self-paced, no application.','Online','certification',array['international','remote','africa','ghana','uk']::text[],array['beginner','secondary','undergraduate']::text[],array['technology']::text[],null::date,'https://www.freecodecamp.org/learn',true,date '2026-11-09','published'),
('CS50x: Introduction to Computer Science','Harvard University','Harvard’s introduction to computer science, free online: lectures, problem sets and a final project. Certificate options are listed on the course site.','Anyone. Self-paced.','Online','training',array['international','remote','africa','ghana','uk']::text[],array['beginner','secondary','undergraduate']::text[],array['technology']::text[],null::date,'https://cs50.harvard.edu/x/',true,date '2026-11-09','published'),
('Cisco Networking Academy courses','Cisco','Self-paced courses in networking, cybersecurity, programming and IT, many of them free, with digital badges on completion.','Anyone with a free account. Some courses run through schools.','Online','training',array['international','remote','africa','ghana','uk']::text[],array['beginner','secondary','undergraduate']::text[],array['technology']::text[],null::date,'https://www.netacad.com/',true,date '2026-11-09','published'),
('Kaggle Learn micro-courses','Kaggle','Short, free, hands-on courses in Python, machine learning, SQL, data visualisation and more, run in the browser.','Anyone with a free Kaggle account.','Online','training',array['international','remote','africa','ghana','uk']::text[],array['beginner','undergraduate']::text[],array['technology']::text[],null::date,'https://www.kaggle.com/learn',true,date '2026-11-09','published'),
('Microsoft Learn training','Microsoft','Free learning paths and modules for Azure, AI, Power Platform, Microsoft 365 and developer tools. Certification exams are separate and usually paid.','Anyone. Self-paced.','Online','training',array['international','remote','africa','ghana','uk']::text[],array['beginner','undergraduate']::text[],array['technology','business']::text[],null::date,'https://learn.microsoft.com/en-us/training/',true,date '2026-11-09','published'),
('GitHub Student Developer Pack','GitHub Education','Free access to developer tools and services for verified students, including GitHub features and partner offers.','Students verified through GitHub Education. Check the site for current rules.','Online','training',array['international','remote','africa','ghana','uk']::text[],array['secondary','undergraduate']::text[],array['technology']::text[],null::date,'https://education.github.com/pack',true,date '2026-11-09','published'),
('Google Summer of Code','Google','A global online programme where new contributors work on open source projects for 12+ weeks with mentors. Dates change every year.','Age and eligibility rules apply: check the official site before applying.','Online','mentorship',array['international','remote','africa','ghana','uk']::text[],array['undergraduate']::text[],array['technology']::text[],null::date,'https://summerofcode.withgoogle.com/',true,date '2026-11-09','published'),
('Outreachy internships','Outreachy','Remote internships in open source and open science, supporting people underrepresented in tech. Application rounds open twice a year.','See the applicant guide on the official site.','Remote','internship',array['international','remote','africa','ghana','uk']::text[],array['undergraduate']::text[],array['technology']::text[],null::date,'https://www.outreachy.org/',true,date '2026-11-09','published')
